    26→/**
    27→ * Should be used by extension filters, aggregators, etc, that use JavaScript to determine if JavaScript is enabled
    28→ * or not.
    29→ */
    30→@PublicApi
    31→public class JavaScriptConfig
    32→{
    33→  public static final int DEFAULT_OPTIMIZATION_LEVEL = 9;
    34→
    35→  private static final JavaScriptConfig ENABLED_INSTANCE = new JavaScriptConfig(true);
    36→
    37→  @JsonProperty
    38→  private final boolean enabled;
    39→
    40→  @JsonCreator
    41→  public JavaScriptConfig(
    42→      @JsonProperty("enabled") boolean enabled
    43→  )
    44→  {
    45→    this.enabled = enabled;
    46→  }
    47→
    48→  public boolean isEnabled()
    49→  {
    50→    return enabled;
    51→  }
    52→
    53→  @Override
    54→  public boolean equals(Object o)
    55→  {
    56→    if (this == o) {
    57→      return true;
    58→    }
    59→    if (o == null || getClass() != o.getClass()) {
    60→      return false;
    61→    }
    62→
    63→    JavaScriptConfig that = (JavaScriptConfig) o;
    64→
    65→    return enabled == that.enabled;
    66→
    67→  }
    68→
    69→  @Override
    70→  public int hashCode()
    71→  {
    72→    return (enabled ? 1 : 0);
    73→  }
    74→
    75→  @Override
    76→  public String toString()
    77→  {
    78→    return "JavaScriptConfig{" +
    79→           "enabled=" + enabled +
    80→           '}';
    81→  }
    82→
    83→  public static JavaScriptConfig getEnabledInstance()
    84→  {
    85→    return ENABLED_INSTANCE;
    86→  }
    87→}
