    40→  private final ExprMacroTable macroTable;
    41→
    42→  @JsonCreator
    43→  public ExpressionTransform(
    44→      @JsonProperty("name") final String name,
    45→      @JsonProperty("expression") final String expression,
    46→      @JacksonInject ExprMacroTable macroTable
    47→  )
    48→  {
    49→    this.name = Preconditions.checkNotNull(name, "name");
    50→    this.expression = Preconditions.checkNotNull(expression, "expression");
    51→    this.macroTable = macroTable;
    52→  }
    53→
    54→  @JsonProperty
    55→  @Override
    56→  public String getName()
    57→  {
    58→    return name;
    59→  }
    60→
    61→  @JsonProperty
    62→  public String getExpression()
    63→  {
    64→    return expression;
    65→  }
    66→
    67→  @Override
    68→  public RowFunction getRowFunction()
    69→  {
    70→    final Expr expr = Parser.parse(expression, Preconditions.checkNotNull(this.macroTable, "macroTable"));
    71→    return new ExpressionRowFunction(expr);
    72→  }
    73→
    74→  static class ExpressionRowFunction implements RowFunction
    75→  {
    76→    private final Expr expr;
    77→
    78→    ExpressionRowFunction(final Expr expr)
    79→    {
    80→      this.expr = expr;
    81→    }
    82→
    83→    @Override
    84→    public Object eval(final Row row)
    85→    {
    86→      return ExpressionSelectors.coerceEvalToSelectorObject(expr.eval(name -> getValueFromRow(row, name)));
    87→    }
    88→  }
    89→
    90→  private static Object getValueFromRow(final Row row, final String column)
    91→  {
    92→    if (column.equals(ColumnHolder.TIME_COLUMN_NAME)) {
    93→      return row.getTimestampFromEpoch();
    94→    } else {
    95→      Object raw = row.getRaw(column);
    96→      if (raw instanceof List) {
    97→        return ExpressionSelectors.coerceListToArray((List) raw);
    98→      }
    99→      return raw;
   100→    }
   101→  }
